export type KoryApiOperationKey = keyof KoryApiOperations;

/** Arguments for `request(key, ...)`: omitted entirely when the operation takes no input. */
export type KoryApiRequestArgs<K extends KoryApiOperationKey> = KoryApiOperations[K] extends {
  input: infer I;
}
  ? undefined extends I
    ? [input?: Exclude<I, undefined>]
    : [input: I]
  : [];

/** Result type for `request(key, ...)`. Responses are the full JSON body (the `ok`/`data` envelope included). */
export type KoryApiResponse<K extends KoryApiOperationKey> = KoryApiOperations[K]['response'];

