export interface KoryApiClientOptions {
  /** Backend origin, e.g. `http://localhost:3001`. A trailing slash is ignored. */
  baseUrl: string;
  /** Supplies the local session bearer token. Called per request; return null to send none. */
  getAuthToken?: () => string | null | undefined | Promise<string | null | undefined>;
  /** Replaces the global `fetch` (tests, custom transports). */
  fetch?: typeof fetch;
}

export class KoryApiError extends Error {
  readonly status: number;
  readonly body: unknown;
  readonly key: string;
  constructor(key: string, status: number, body: unknown) {
    super(`${key} failed with HTTP ${status}`);
    this.name = 'KoryApiError';
    this.key = key;
    this.status = status;
    this.body = body;
  }
}

export interface KoryApiClient {
  request<K extends KoryApiOperationKey>(
    key: K,
    ...args: KoryApiRequestArgs<K>
  ): Promise<KoryApiResponse<K>>;
}

export function createKoryApiClient(options: KoryApiClientOptions): KoryApiClient {
  const baseUrl = options.baseUrl.replace(/\/+$/, '');
  const fetchImpl = options.fetch ?? globalThis.fetch;
  return {
    async request<K extends KoryApiOperationKey>(key: K, ...args: KoryApiRequestArgs<K>) {
      const input = (args[0] ?? undefined) as
        | { params?: Record<string, unknown>; query?: Record<string, unknown>; body?: unknown }
        | undefined;
      const route = KORY_API_ROUTES[key];
      const path = route.path.replace(/\{([^}]+)\}/g, (_match, name: string) => {
        const value = input?.params?.[name];
        if (value === undefined || value === null)
          throw new Error(`${key} requires path parameter ${name}`);
        return encodeURIComponent(String(value));
      });
      const search = new URLSearchParams();
      for (const [name, value] of Object.entries(input?.query ?? {})) {
        if (value === undefined || value === null) continue;
        const values = Array.isArray(value) ? value : [value];
        for (const item of values) {
          search.append(name, typeof item === 'object' ? JSON.stringify(item) : String(item));
        }
      }
      const query = search.toString();
      const headers: Record<string, string> = { accept: 'application/json' };
      const token = options.getAuthToken ? await options.getAuthToken() : null;
      if (token) headers['authorization'] = `Bearer ${token}`;
      const init: RequestInit = { method: route.method, headers };
      if (input?.body !== undefined) {
        headers['content-type'] = 'application/json';
        init.body = JSON.stringify(input.body);
      }
      const url = `${baseUrl}${path}${query ? `?${query}` : ''}`;
      const response = await fetchImpl(url, init);
      const text = await response.text();
      let body: unknown = undefined;
      if (text.length > 0) {
        try {
          body = JSON.parse(text);
        } catch {
          body = text;
        }
      }
      if (!response.ok) throw new KoryApiError(key, response.status, body);
      return body as KoryApiResponse<K>;
    },
  };
}
